// Learn Logo, part 2: units 9 to 16 (words, lists, recursion, loops and templates,
// input and events, keeping data, power tools, and a capstone game).
(function (LG) {
  'use strict';
  LG.LESSONS = (LG.LESSONS || []).concat([

    // ---- 9. Words ------------------------------------------------------------------------------
    { id: 'words-pieces', unit: '9. Words', title: 'Words and their pieces', level: 'Everyone', minutes: 8,
      summary: 'Quote a word, glue words together with WORD, and take them apart with FIRST, LAST, BUTFIRST, COUNT and ITEM.',
      steps: [
        { title: 'Words, not just numbers', sel: '#cmdCard', text: 'Logo works with <b>words</b> as well as numbers. A quote mark in front of a word means "this is just a word, do not run it". So <code>print "hello</code> prints hello. The quote goes only at the front, never at the end.' },
        { title: 'Print a word', sel: '#cmdInputBox', text: 'Type <code>print "hello</code> and press <kbd>Enter</kbd>.', check: { command: '^\\s*(print|pr|show)\\s+"\\w' }, hint: 'The quote mark goes right before the word, with no space: <code>"hello</code>.' },
        { title: 'Without the quote', sel: '#cmdInputBox', text: 'Now leave the quote out: type <code>print hello</code>. Logo thinks HELLO is a command and tells you it does not know how to do it. That is why words need the quote.', check: { command: '^\\s*(print|pr)\\s+[a-z]' } },
        { title: 'Gluing words together', sel: '#cmdInputBox', text: '<code>word</code> joins two words into one. Try <code>print word "sun "flower</code>.<br>To join more than two, put parentheses around the whole thing: <code>print (word "rain "bow "s)</code>.', check: { command: '\\bword\\b' } },
        { title: 'Taking words apart', sel: '#cmdInputBox', text: 'These take a word apart:<pre>first "turtle      t\nlast "turtle       e\nbutfirst "turtle   urtle\nbutlast "turtle    turtl</pre><code>bf</code> and <code>bl</code> are short for butfirst and butlast. Try <code>print butfirst "turtle</code>.', check: { command: '\\b(butfirst|bf|butlast|bl|first|last)\\b' } },
        { title: 'Count and item', sel: '#cmdInputBox', text: '<code>count</code> tells how many letters a word has, and <code>item</code> picks one out by its number. Try <code>print count "elephant</code> and then <code>print item 3 "elephant</code>.', check: { command: '\\bitem\\b' }, hint: 'ITEM takes the number first, then the word: <code>item 3 "elephant</code> is p.' },
        { title: 'A program with words', sel: '#editorCard', text: 'Here is a procedure that makes initials out of two names. It does not print anything itself: <code>output</code> hands the new word back to whoever used INITIALS, here PRINT. A procedure that outputs is called an <b>operation</b>, like FIRST or SUM. Press <kbd>F5</kbd> to run it.', code: 'to initials :given :family\n  output word first :given first :family\nend\n\nprint initials "Ada "Lovelace\nprint initials "Alan "Turing\n', check: { run: true } },
        { title: 'Your turn', sel: '#editorCard', text: 'Add a line at the end that prints the <b>last</b> letter of your own name, like <code>print last "Maya</code>. Then run it again.', check: { codeHas: '(print|pr|show)\\s+last\\s+"' }, hint: 'Type <code>print last "</code> and your name on a new line at the bottom.' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>butfirst "logo</code> give?', options: ['ogo', 'l', 'log'], answer: 0, explain: 'BUTFIRST gives everything except the first letter.' } },
        { title: 'One more', quiz: { q: 'Why does <code>print "hello</code> need the quote mark?', options: ['So Logo treats hello as a word instead of a command to run', 'To make the word print in capitals', 'Every line needs a quote'], answer: 0, explain: 'Without the quote, Logo looks for a procedure called HELLO.' } },
      ] },

    { id: 'words-letters', unit: '9. Words', title: 'Big letters, small letters, secret codes', level: 'Everyone', minutes: 8,
      summary: 'Change case with UPPERCASE and LOWERCASE, and turn letters into numbers and back with ASCII and CHAR.',
      steps: [
        { title: 'Shout and whisper', sel: '#cmdInputBox', text: '<code>uppercase</code> outputs a word in capital letters and <code>lowercase</code> in small ones. Try <code>print uppercase "quiet</code>.', check: { command: '\\b(uppercase|lowercase)\\b' } },
        { title: 'Case does not matter to =', sel: '#cmdInputBox', text: 'When Logo compares words it ignores capitals. Try <code>show "Hello = "hello</code>. It says <b>true</b>.', check: { command: '"\\w+\\s*=\\s*"\\w' } },
        { title: 'Letters are numbers inside', sel: '#cmdInputBox', text: 'Inside the computer every character has a number, called its <b>ASCII code</b>. Try <code>print ascii "A</code>. Capital A is 65, B is 66, and so on. Small a is 97.', check: { command: '\\bascii\\b' } },
        { title: 'And back again', sel: '#cmdInputBox', text: '<code>char</code> goes the other way: it turns a number into a character. Try <code>print char 66</code>.', check: { command: '\\bchar\\b' } },
        { title: 'The alphabet', sel: '#editorCard', text: 'This prints the whole alphabet. <code>type</code> prints without starting a new line, and <code>char 64 + repcount</code> is A the first time, B the second, and so on. Run it.', code: 'repeat 26 [type char 64 + repcount]\nprint "\n', check: { output: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' } },
        { title: 'A secret code', sel: '#editorCard', text: 'SHIFT moves a letter one step along the alphabet: it adds 1 to the letter\'s code. Run it and see which famous computer name appears.', code: 'to shift :letter\n  output char 1 + ascii :letter\nend\n\nprint (word shift "h shift "a shift "l)\n', check: { output: 'ibm' } },
        { title: 'Crack the code', sel: '#editorCard', text: 'Write a procedure <code>unshift</code> that moves a letter one step <i>back</i>. Then add <code>print (word unshift "i unshift "c unshift "n)</code> and run it.', check: { defined: 'unshift' }, hint: '<pre>to unshift :letter\n  output char (ascii :letter) - 1\nend</pre>' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>print char 97</code> show?', options: ['a', 'A', '97'], answer: 0, explain: 'Small letters start at 97, capitals at 65.' } },
        { title: 'One more', quiz: { q: 'What does <code>show "CAT = "cat</code> say?', options: ['true', 'false', 'An error'], answer: 0, explain: 'Logo ignores capitals when it compares words.' } },
      ] },

    { id: 'words-recursion', unit: '9. Words', title: 'A word, one letter at a time', level: 'Everyone', minutes: 10,
      summary: 'Write procedures that call themselves on a shorter and shorter word: reverse a word and count its vowels.',
      steps: [
        { title: 'First letter, and the rest', text: 'Every word is its first letter plus the rest. A procedure can deal with the first letter and hand the rest to <i>itself</i>. The rest gets shorter each time, until nothing is left. Then it must stop. A word with nothing left in it is the <b>empty word</b>, written as a quote all by itself.' },
        { title: 'The empty word', sel: '#cmdInputBox', text: '<code>emptyp</code> answers true when a word is empty. Try <code>show emptyp "</code> and then <code>show emptyp bf "a</code>.', check: { command: '\\b(emptyp|empty\\?)\\b' } },
        { title: 'Backwards', sel: '#editorCard', text: 'BACKWARDS takes the last letter and puts the rest, reversed, after it. If the word is empty it outputs the empty word: that is the <b>stop rule</b>. Run it.', code: 'to backwards :w\n  if emptyp :w [output "]\n  output word last :w backwards butlast :w\nend\n\nprint backwards "turtle\nprint backwards "stressed\n', check: { output: 'desserts' } },
        { title: 'How it works', text: 'Follow it for a short word:<pre>backwards "abc\n= word "c backwards "ab\n= word "c word "b backwards "a\n= word "c word "b word "a backwards "\n= word "c word "b word "a "\n= cba</pre>Each BACKWARDS waits for the smaller one inside it to finish.' },
        { title: 'Try it yourself', sel: '#cmdInputBox', text: 'The procedure stays defined after the run. Type <code>print backwards "racecar</code>. Some words read the same both ways!', check: { command: '\\bbackwards\\b' } },
        { title: 'Counting vowels', sel: '#editorCard', text: 'VOWELS looks at the first letter: if it is a vowel it counts 1, then adds the vowels in the rest. <code>memberp</code> checks whether a letter is in the word "aeiou. Run it.', code: 'to vowels :w\n  if emptyp :w [output 0]\n  if memberp first :w "aeiou [output 1 + vowels butfirst :w]\n  output vowels butfirst :w\nend\n\nprint vowels "elephant\nprint vowels "rhythm\n', check: { run: true } },
        { title: 'Challenge: a palindrome test', sel: '#editorCard', text: 'A palindrome reads the same both ways. Add a procedure <code>palindromep</code> to the program that outputs true or false, using BACKWARDS. (Logo names that answer true or false often end in P, for "predicate".) Copy BACKWARDS from step 3 into this program too, then run it.', check: { defined: 'palindromep' }, hint: '<pre>to palindromep :w\n  output :w = backwards :w\nend</pre>' },
        { title: 'Test it', sel: '#cmdInputBox', text: 'Try <code>show palindromep "level</code> and <code>show palindromep "logo</code>.', check: { command: '\\bpalindromep\\b' } },
        { title: 'Quick quiz', quiz: { q: 'In BACKWARDS, what is the line <code>if emptyp :w [output "]</code> for?', options: ['It is the stop rule: without it BACKWARDS would call itself forever', 'It prints a blank line', 'It removes the spaces'], answer: 0, explain: 'Every recursive procedure needs a case where it stops calling itself.' } },
        { title: 'One more', quiz: { q: 'What does <code>vowels "moon</code> output?', options: ['2', '1', '4'], answer: 0, explain: 'Two o letters, so 2.' } },
      ] },

    // ---- 10. Lists -----------------------------------------------------------------------------
    { id: 'lists-making', unit: '10. Lists', title: 'Lists: words in a row', level: 'Everyone', minutes: 8,
      summary: 'Make lists with square brackets, LIST and SENTENCE, and grow them with FPUT and LPUT.',
      steps: [
        { title: 'Square brackets', sel: '#cmdInputBox', text: 'A <b>list</b> is a row of words inside square brackets. Inside a list you do not need quote marks. Try <code>print [I like turtles]</code> and then <code>show [I like turtles]</code>. PRINT leaves off the outer brackets, SHOW keeps them.', check: { command: '\\[' } },
        { title: 'Lists inside lists', sel: '#cmdInputBox', text: 'A list can hold other lists. Try <code>show [[1 2] [3 4] five]</code>. That list has three members: two lists and a word.', check: { command: '\\[\\s*\\[' } },
        { title: 'LIST or SENTENCE?', sel: '#cmdInputBox', text: 'Both make lists, but differently. Try both:<pre>show list [a b] [c d]\nshow sentence [a b] [c d]</pre>LIST keeps each input as one member. SENTENCE (or SE) pours the members together into one flat list.', check: { command: '\\b(sentence|se)\\b' } },
        { title: 'Words into lists', sel: '#cmdInputBox', text: 'With words they agree: <code>show list "hello "world</code> and <code>show sentence "hello "world</code> both give [hello world]. With more than two inputs, use parentheses: <code>show (sentence "one [two three] "four)</code>.', check: { command: '\\(\\s*(sentence|se|list)\\b' } },
        { title: 'Adding one thing', sel: '#cmdInputBox', text: '<code>fput</code> puts something at the <b>front</b> of a list and <code>lput</code> at the <b>end</b> (L for last). Try <code>show fput "red [green blue]</code> and <code>show lput "pink [green blue]</code>.', check: { command: '\\b(fput|lput)\\b' } },
        { title: 'A growing list', sel: '#editorCard', text: 'FPUT and LPUT do not change the old list: they output a new one. To keep it, MAKE the variable again. Run this.', code: 'make "pets []\nmake "pets lput "cat :pets\nmake "pets lput "dog :pets\nmake "pets fput "fish :pets\nprint :pets\nshow :pets\n', check: { run: true } },
        { title: 'Your turn', sel: '#editorCard', text: 'Add a line before the PRINT that puts <code>"hamster</code> at the end of the list. Then run it again.', check: { codeHas: 'make\\s+"pets\\s+lput\\s+"hamster' }, hint: '<code>make "pets lput "hamster :pets</code>' },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd> and check that the hamster is last.', check: { output: 'hamster' } },
        { title: 'Quick quiz', quiz: { q: 'What does <code>show list [a b] [c d]</code> show?', options: ['[[a b] [c d]]', '[a b c d]', '[a b] [c d]'], answer: 0, explain: 'LIST keeps each input whole. SENTENCE would give [a b c d].' } },
        { title: 'One more', quiz: { q: 'Where does FPUT put the new member?', options: ['At the front', 'At the end', 'In the middle'], answer: 0, explain: 'F for first. LPUT puts it last.' } },
      ] },

    { id: 'lists-pieces', unit: '10. Lists', title: 'Looking inside a list', level: 'Everyone', minutes: 8,
      summary: 'Use FIRST, LAST, BUTFIRST, ITEM and COUNT on lists, and ask questions with EMPTYP and MEMBERP.',
      steps: [
        { title: 'The same tools', sel: '#editorCard', text: 'The tools that take words apart also work on lists. With a list they work on whole members, not letters. Run this and compare each line with its output.', code: 'make "fruit [apple banana cherry]\nprint first :fruit\nprint last :fruit\nshow butfirst :fruit\nprint item 2 :fruit\nprint count :fruit\nprint first last :fruit\n', check: { run: true } },
        { title: 'Reading from the right', text: 'The last line, <code>first last :fruit</code>, is read from the right: LAST gives the word cherry, then FIRST gives its first letter, c.' },
        { title: 'Try it', sel: '#cmdInputBox', text: 'The variable is still there after the run. Type <code>print item 3 :fruit</code>.', check: { command: '\\bitem\\b' } },
        { title: 'Is it empty?', sel: '#cmdInputBox', text: '<code>emptyp</code> works on lists too. Try <code>show emptyp []</code> and <code>show emptyp butfirst [one]</code>.', check: { command: '\\b(emptyp|empty\\?)\\b' } },
        { title: 'Is it in there?', sel: '#cmdInputBox', text: '<code>memberp</code> answers whether something is a member of a list. Try <code>show memberp "banana :fruit</code> and <code>show memberp "mango :fruit</code>.', check: { command: '\\b(memberp|member\\?)\\b' } },
        { title: 'A fruit checker', sel: '#editorCard', text: 'Here MEMBERP makes a decision. Run it.', code: 'make "fruit [apple banana cherry]\n\nto in.bowl :f\n  ifelse memberp :f :fruit [print sentence :f [is in the bowl.]] [print sentence :f [is not in the bowl.]]\nend\n\nin.bowl "banana\nin.bowl "mango\n', check: { output: 'mango is not' } },
        { title: 'Your turn', sel: '#cmdInputBox', text: 'Ask about another fruit from the command center, like <code>in.bowl "cherry</code>.', check: { command: '\\bin\\.bowl\\b' } },
        { title: 'Quick quiz', quiz: { q: 'What is <code>count [[a b] c]</code>?', options: ['2', '3', '1'], answer: 0, explain: 'The list has two members: the list [a b] and the word c.' } },
        { title: 'One more', quiz: { q: 'What does <code>memberp "an [banana]</code> say?', options: ['false', 'true'], answer: 0, explain: 'MEMBERP looks for a whole member. The only member is banana, and "an is not equal to it.' } },
      ] },

    { id: 'lists-random', unit: '10. Lists', title: 'PICK and random sentences', level: 'Kids', minutes: 7,
      summary: 'Let PICK choose from a list to make silly sentences and colorful pictures.',
      steps: [
        { title: 'Heads or tails', sel: '#cmdInputBox', text: '<code>pick</code> chooses one member of a list at random. Type <code>print pick [heads tails]</code> a few times. Press the up arrow key to get the last command back.', check: { command: '\\bpick\\b' } },
        { title: 'A silly sentence machine', sel: '#editorCard', text: 'SILLY picks one word from each list and joins them with SENTENCE. Because SENTENCE has more than two inputs here, the whole thing is in parentheses. Run it a few times.', code: 'to silly\n  output (sentence pick [the a my] pick [purple sleepy giant tiny] pick [cat turtle robot dragon] pick [eats sings juggles paints] pick [pizza socks rainbows moonlight])\nend\n\nrepeat 5 [print silly]\n', check: { run: true } },
        { title: 'Add your own words', sel: '#editorCard', text: 'Put some of your own words into the lists (any list you like), then run it again.', check: { run: true } },
        { title: 'Random colors', sel: '#editorCard', text: 'PICK can choose colors too, and a color can be a name or a list of red, green and blue. Run this row of stars.', code: 'clearscreen\npenup setxy -300 0 pendown\nrepeat 6 [\n  setpencolor pick [red orange green blue purple [255 0 160]]\n  repeat 5 [forward 60 right 144]\n  penup right 90 forward 100 left 90 pendown\n]\n', check: { drawn: 20 } },
        { title: 'Quick quiz', quiz: { q: 'Why is <code>(sentence pick [a b] pick [c d] pick [e f])</code> in parentheses?', options: ['SENTENCE takes two inputs unless you put parentheses around it', 'Parentheses make PICK random', 'Lists always need parentheses'], answer: 0, explain: 'Like WORD and LIST, SENTENCE can take more inputs when it is wrapped in parentheses.' } },
      ] },

    // ---- 11. Recursion -------------------------------------------------------------------------
    { id: 'recursion-spiral', unit: '11. Recursion', title: 'A procedure that calls itself', level: 'Everyone', minutes: 8,
      summary: 'Draw a spiral with a procedure that calls itself, and learn why it needs a stop rule.',
      steps: [
        { title: 'Calling yourself', text: 'A procedure can use any word Logo knows, and that includes <i>its own name</i>. This is called <b>recursion</b>. Each time, the procedure does a little bit of work and then asks a copy of itself to do the rest.' },
        { title: 'A spiral', sel: '#editorCard', text: 'SPIRAL draws one side, turns, and then calls SPIRAL with a slightly longer side. The first line is the <b>stop rule</b>: when the side gets too long, it stops. Run it.', code: 'to spiral :size\n  if :size > 200 [stop]\n  forward :size\n  right 90\n  spiral :size + 5\nend\n\nclearscreen\nspiral 5\n', check: { drawn: 30 } },
        { title: 'Many copies', text: 'Each SPIRAL has its own <code>:size</code>: 5, then 10, then 15, and so on. When <code>:size</code> reaches 205, the stop rule ends that copy, then the one before it, all the way back to the first.' },
        { title: 'Twist it', sel: '#editorCard', text: 'Change <code>right 90</code> to another angle, like 91, 121 or 144, and run it again.', check: { codeHas: 'right\\s+(?!90\\b)\\d+' } },
        { title: 'Run it', sel: '#tbRun', text: 'Press <kbd>F5</kbd> to see the new spiral.', check: { run: true } },
        { title: 'Try from the command center', sel: '#cmdInputBox', text: 'Type <code>clearscreen spiral 50</code>. The spiral starts bigger, so it has fewer sides before the stop rule ends it.', check: { command: '\\bspiral\\b' } },
        { title: 'Without a stop rule', text: 'If you took away the stop rule, SPIRAL would call itself forever and the turtle would walk off the screen. If that ever happens to one of your programs, press <b>Stop</b> (<kbd>Shift+F5</kbd>).' },
        { title: 'Quick quiz', quiz: { q: 'What does the line <code>if :size > 200 [stop]</code> do?', options: ['It ends the recursion when the sides get long enough', 'It makes the turtle turn', 'It makes each side 200 steps'], answer: 0, explain: 'That is the stop rule. Without it, SPIRAL never ends.' } },
        { title: 'One more', quiz: { q: 'If the stop rule were <code>if :size > 100 [stop]</code>, the spiral would be...', options: ['Smaller, with fewer sides', 'Bigger', 'Exactly the same'], answer: 0, explain: 'It would stop as soon as a side is longer than 100.' } },
      ] },

    { id: 'recursion-trees', unit: '11. Recursion', title: 'Recursive trees', level: 'Everyone', minutes: 9,
      summary: 'Grow a tree where every branch is a smaller tree.',
      steps: [
        { title: 'Trees are made of trees', text: 'Look at a real tree: the trunk splits into branches, and each branch looks like a small tree. That is recursion in nature. In Logo: a tree is a trunk with two smaller trees on top.' },
        { title: 'Grow one', sel: '#editorCard', text: 'TREE draws a trunk, turns left and grows a smaller tree, turns right and grows another, then turns back and walks back down. Run it.', code: 'to tree :size\n  if :size < 5 [stop]\n  forward :size\n  left 30\n  tree :size * 0.7\n  right 60\n  tree :size * 0.7\n  left 30\n  back :size\nend\n\nclearscreen\npenup setxy 0 -200 pendown\ntree 100\n', check: { drawn: 50 } },
        { title: 'Back where it started', text: 'The secret is the end: <code>left 30</code> and <code>back :size</code> undo the turns and walks. So every TREE leaves the turtle exactly where and how it found it. That is why the second branch starts in the right place.' },
        { title: 'Plant another', sel: '#cmdInputBox', text: 'Type <code>penup setxy -250 -200 pendown tree 50</code> to plant a small tree on the left.', check: { command: '\\btree\\s+\\d' } },
        { title: 'Experiment', sel: '#editorCard', text: 'Change the program: try <code>0.6</code> or <code>0.75</code> instead of 0.7, or 20 and 40 instead of 30 and 60. Run it each time.', check: { run: true } },
        { title: 'Slow motion', sel: '#speed', text: 'Move the speed slider to the left and run it again. Watch the order: the turtle finishes the whole left part before it starts on the right.' },
        { title: 'Quick quiz', quiz: { q: 'What would happen without <code>back :size</code> at the end?', options: ['The turtle would not get back to the bottom of each branch, so the tree would come out scrambled', 'Nothing would change', 'The tree would be drawn twice'], answer: 0, explain: 'Each TREE must leave the turtle where it started, or the next branch starts in the wrong place.' } },
        { title: 'One more', quiz: { q: 'What makes TREE stop?', options: ['When <code>:size</code> is smaller than 5', 'When the turtle reaches the top of the screen', 'After 100 branches'], answer: 0, explain: 'Each smaller tree is 0.7 times as big, so the size gets small enough sooner or later.' } },
      ] },

    { id: 'recursion-output', unit: '11. Recursion', title: 'Recursive operations', level: 'Intermediate', minutes: 9,
      summary: 'Use OUTPUT in recursive procedures: factorial and the sum of a list.',
      steps: [
        { title: 'Recursion that answers', text: 'SPIRAL and TREE are <b>commands</b>: they do something. BACKWARDS and VOWELS were <b>operations</b>: they OUTPUT an answer. A recursive operation builds its answer from the answer of a smaller copy of itself. OUTPUT also ends the procedure straight away, like STOP.' },
        { title: 'Factorial', sel: '#editorCard', text: '5 factorial is 5 x 4 x 3 x 2 x 1. Put another way: the factorial of N is N times the factorial of N - 1, and the factorial of 0 is 1. The program says exactly that. Run it.', code: 'to factorial :n\n  if :n = 0 [output 1]\n  output :n * factorial :n - 1\nend\n\nprint factorial 5\n', check: { output: '120' } },
        { title: 'Waiting for answers', text: 'FACTORIAL 5 cannot finish until FACTORIAL 4 gives its answer, which waits for FACTORIAL 3, and so on down to FACTORIAL 0, which outputs 1 at once. Then the answers come back up: 1, 1, 2, 6, 24, 120.' },
        { title: 'Bigger', sel: '#cmdInputBox', text: 'Try <code>print factorial 10</code>. Factorials grow very fast.', check: { command: '\\bfactorial\\s+\\d' } },
        { title: 'Adding up a list', sel: '#editorCard', text: 'SUM.LIST adds the first number to the sum of the rest. The sum of an empty list is 0: that is the stop rule. Notice the parentheses around <code>(first :numbers)</code>: without them, Logo would do the + first and try to add a list. Run it.', code: 'to sum.list :numbers\n  if emptyp :numbers [output 0]\n  output (first :numbers) + sum.list butfirst :numbers\nend\n\nprint sum.list [3 5 10]\n', check: { output: '18' } },
        { title: 'Challenge: multiply them', sel: '#editorCard', text: 'Add a procedure <code>product.list</code> that multiplies all the numbers in a list, and run the program. What should an empty list output this time?', check: { defined: 'product.list' }, hint: '<pre>to product.list :numbers\n  if emptyp :numbers [output 1]\n  output (first :numbers) * product.list butfirst :numbers\nend</pre>The empty list outputs 1, because multiplying by 1 changes nothing.' },
        { title: 'Test it', sel: '#cmdInputBox', text: 'Type <code>print product.list [2 3 4]</code>.', check: { output: '\\b24\\b' } },
        { title: 'Quick quiz', quiz: { q: 'Why does FACTORIAL need <code>if :n = 0 [output 1]</code>?', options: ['It is the stop rule, the one answer known without asking a smaller copy', 'To print the answer', 'Because 0 is not a number'], answer: 0, explain: 'Every recursive operation needs a simplest case it can answer straight away.' } },
        { title: 'One more', quiz: { q: 'What goes wrong with <code>output first :numbers + sum.list butfirst :numbers</code>?', options: ['The + happens first, so FIRST would get a sum instead of the list', 'Nothing, it is the same', 'It adds the numbers twice'], answer: 0, explain: 'Infix operations like + bind tighter than inputs, so wrap (first :numbers) in parentheses.' } },
      ] },

    { id: 'recursion-debugger', unit: '11. Recursion', title: 'Watching recursion in the debugger', level: 'Everyone', minutes: 6,
      summary: 'Stop a recursive program in the middle and see every copy of the procedure waiting on the call stack.', tour: 'debug' },

    { id: 'recursion-lists', unit: '11. Recursion', title: 'Recursion on lists', level: 'Intermediate', minutes: 10,
      summary: 'Build new lists recursively: change every member, or keep only some of them.',
      steps: [
        { title: 'The list pattern', text: 'Most recursive list procedures look the same:<pre>if emptyp :list [output []]\noutput fput (something with first :list) (the same procedure on butfirst :list)</pre>An empty list in, an empty list out. Otherwise, deal with the first member and let a copy handle the rest.' },
        { title: 'Double everything', sel: '#editorCard', text: 'DOUBLE.ALL makes a new list with every number doubled. Run it.', code: 'to double.all :list\n  if emptyp :list [output []]\n  output fput 2 * first :list double.all butfirst :list\nend\n\nshow double.all [1 2 3 4]\n', check: { output: '\\[2 4 6 8\\]' } },
        { title: 'Keep only some', sel: '#editorCard', text: 'EVENS keeps only the even numbers. There are now <i>two</i> cases after the stop rule: keep the first member, or skip it. Run it.', code: 'to evens :list\n  if emptyp :list [output []]\n  if 0 = remainder first :list 2 [output fput first :list evens butfirst :list]\n  output evens butfirst :list\nend\n\nshow evens [1 2 3 4 5 6 7 8]\n', check: { output: '\\[2 4 6 8\\]' } },
        { title: 'Try other lists', sel: '#cmdInputBox', text: 'Type <code>show evens [10 15 20 25]</code>. What does <code>show evens [1 3 5]</code> give?', check: { command: '\\bevens\\b' } },
        { title: 'Challenge: SHOUT.ALL', sel: '#editorCard', text: 'Write <code>shout.all</code>, which outputs a list with every word in capitals, using the same pattern as DOUBLE.ALL and UPPERCASE. Run the program to define it.', check: { defined: 'shout.all' }, hint: '<pre>to shout.all :list\n  if emptyp :list [output []]\n  output fput uppercase first :list shout.all butfirst :list\nend</pre>' },
        { title: 'Test it', sel: '#cmdInputBox', text: 'Type <code>show shout.all [hello there]</code>.', check: { output: 'HELLO THERE' } },
        { title: 'There is a shortcut', text: 'Changing every member and keeping some members are so common that Logo has MAP and FILTER to do them for you. You will meet them in the next unit. Now you know what they do inside.' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>double.all []</code> output?', options: ['[]', '0', 'An error'], answer: 0, explain: 'The stop rule: an empty list in, an empty list out.' } },
        { title: 'One more', quiz: { q: 'In EVENS, what happens to an odd number?', options: ['It is skipped: EVENS just outputs the result for the rest', 'It is doubled', 'The procedure stops'], answer: 0, explain: 'The last line outputs <code>evens butfirst :list</code> without putting the odd number in.' } },
      ] },

    // ---- 12. Loops and templates ---------------------------------------------------------------
    { id: 'loops-for', unit: '12. Loops and templates', title: 'Counting with FOR', level: 'Everyone', minutes: 8,
      summary: 'Let FOR count for you, by ones, by bigger steps, or backwards.',
      steps: [
        { title: 'A loop with a counter', sel: '#cmdInputBox', text: 'REPEAT does something a number of times. FOR does the same but gives the counter a name, so you can use it. Type <code>for [i 1 5] [print :i]</code>.', check: { command: '\\bfor\\s*\\[' } },
        { title: 'Bigger steps', sel: '#cmdInputBox', text: 'A fourth number in the brackets is the step. Try <code>for [i 0 100 25] [print :i]</code>.', check: { command: '\\bfor\\s*\\[\\s*\\S+\\s+\\S+\\s+\\S+\\s+\\S+\\s*\\]' } },
        { title: 'Counting down', sel: '#cmdInputBox', text: 'If the start is bigger than the end, FOR counts down. Try <code>for [i 5 1] [print :i]</code>, or with a step: <code>for [i 10 0 -2] [print :i]</code>.', check: { command: '\\bfor\\s*\\[\\s*\\w+\\s+(\\d+)\\s+\\d' } },
        { title: 'Drawing with FOR', sel: '#editorCard', text: 'The counter can be used as a length. Each side is 10 steps longer than the one before. Run it.', code: 'clearscreen\nfor [size 10 300 10] [forward :size right 90]\n', check: { drawn: 20 } },
        { title: 'Change it', sel: '#editorCard', text: 'Try a step of 5 instead of 10, and turn 89 instead of 90. Run it.', check: { run: true } },
        { title: 'A times table', sel: '#editorCard', text: 'FOR is handy for tables. Run this one, then change the 7 to another number.', code: 'for [i 1 10] [print (sentence 7 "x :i "= 7 * :i)]\n', check: { output: '7 x 10 = 70' } },
        { title: 'Quick quiz', quiz: { q: 'How many numbers does <code>for [i 0 20 5] [print :i]</code> print?', options: ['5', '4', '20'], answer: 0, explain: '0, 5, 10, 15 and 20.' } },
      ] },

    { id: 'loops-while', unit: '12. Loops and templates', title: 'WHILE, UNTIL and FOREVER', level: 'Everyone', minutes: 9,
      summary: 'Loops that keep going while a condition holds, and FOREVER loops that STOP.',
      steps: [
        { title: 'Loop while it is true', sel: '#editorCard', text: 'WHILE runs its instructions again and again as long as the condition is true. The condition is in square brackets so Logo can check it again each time round. Run it.', code: 'make "n 1\nwhile [:n < 100] [print :n make "n :n * 2]\n', check: { output: '64' } },
        { title: 'Loop until it is true', sel: '#cmdInputBox', text: 'UNTIL is the opposite: it keeps going until the condition becomes true. Type <code>make "n 0 until [:n > 10] [make "n :n + 3 print :n]</code>.', check: { command: '\\buntil\\s*\\[' } },
        { title: 'At least once', sel: '#editorCard', text: 'WHILE checks before each go, so it might never run at all. DO.WHILE checks <i>after</i>, so it always runs at least once. (DO.UNTIL is the same idea with UNTIL.) Run this and see which one printed.', code: 'make "n 100\nwhile [:n < 10] [print [while ran]]\ndo.while [print [do.while ran]] [:n < 10]\n', check: { output: 'do\\.while ran' } },
        { title: 'Forever, until STOP', sel: '#editorCard', text: 'FOREVER never ends by itself. Inside a procedure, STOP ends the whole procedure, and the FOREVER with it. WANDER walks at random until it leaves a circle. Run it.', code: 'to wander\n  forever [\n    if (distance [0 0]) > 150 [print [Out of the circle!] stop]\n    right (random 90) - 45\n    forward 10\n  ]\nend\n\nclearscreen\nwander\n', check: { output: 'out of the circle' } },
        { title: 'STOP needs a procedure', text: 'STOP ends the procedure it is in. That is why the FOREVER is inside WANDER. A FOREVER typed straight into the command center can only be ended with the <b>Stop</b> button.' },
        { title: 'Run it again', sel: '#tbRun', text: 'Run WANDER a few more times. The walk is different every time, but it always stops.', check: { run: true } },
        { title: 'Quick quiz', quiz: { q: 'What is the difference between WHILE and DO.WHILE?', options: ['DO.WHILE always runs its instructions at least once', 'WHILE is faster', 'DO.WHILE never stops'], answer: 0, explain: 'DO.WHILE checks the condition after each go, WHILE before.' } },
        { title: 'One more', quiz: { q: 'How can a FOREVER loop inside a procedure end?', options: ['With STOP (or OUTPUT) inside the loop', 'It ends after 1000 times', 'It cannot'], answer: 0, explain: 'STOP ends the procedure, and the loop with it.' } },
      ] },

    { id: 'loops-foreach-map', unit: '12. Loops and templates', title: 'FOREACH, MAP and FILTER', level: 'Intermediate', minutes: 9,
      summary: 'Run a template for every member of a list with FOREACH, and build new lists with MAP and FILTER.',
      steps: [
        { title: 'For each member', sel: '#cmdInputBox', text: 'FOREACH runs some instructions once for every member of a list. Inside, <code>?</code> stands for the current member. Type <code>foreach [red green blue] [print ?]</code>.', check: { command: '\\bforeach\\b' } },
        { title: 'Which one is it?', sel: '#cmdInputBox', text: '<code>#</code> is the position of the current member: 1, 2, 3... Type <code>foreach [gold silver bronze] [print (sentence # ?)]</code>.', check: { command: '#' } },
        { title: 'Instructions with blanks', text: 'A list like <code>[print ?]</code> is called a <b>template</b>: instructions with a blank in them. FOREACH fills in the blank each time.' },
        { title: 'Turtle templates', sel: '#editorCard', text: 'Each color in the list gets its own hexagon. Run it.', code: 'clearscreen\nforeach [red orange green blue purple] [\n  setpencolor ?\n  repeat 6 [forward 50 right 60]\n  right 72\n]\n', check: { drawn: 20 } },
        { title: 'MAP makes a new list', sel: '#cmdInputBox', text: 'MAP fills the template with each member and collects the answers in a new list. Type <code>show map [? * 10] [1 2 3]</code>.', check: { command: '\\bmap\\b' } },
        { title: 'FILTER keeps some', sel: '#cmdInputBox', text: 'FILTER keeps the members for which the template says true. Type <code>show filter [? > 5] [3 8 1 9 6]</code>.', check: { command: '\\bfilter\\b' } },
        { title: 'More examples', sel: '#editorCard', text: 'Compare these with DOUBLE.ALL and EVENS from the recursion unit: one line each. A template can also be just the name of a procedure, like <code>"uppercase</code>. And MAP and FILTER work on the letters of a word too. Run it.', code: 'show map [2 * ?] [1 2 3 4]\nshow filter [0 = remainder ? 2] [1 2 3 4 5 6]\nshow map "uppercase [quiet please]\nshow map [word ? ?] "abc\nshow filter [memberp ? "aeiou] "education\n', check: { output: 'euaio' } },
        { title: 'Quick quiz', quiz: { q: 'What does <code>show map [? + 1] [1 2 3]</code> show?', options: ['[2 3 4]', '[1 2 3 1]', '7'], answer: 0, explain: 'MAP adds 1 to each member and collects the answers.' } },
        { title: 'One more', quiz: { q: 'What does <code>show filter [(count ?) = 3] [cat bird dog fish]</code> show?', options: ['[cat dog]', '[bird fish]', '2'], answer: 0, explain: 'Only cat and dog have exactly three letters.' } },
      ] },

    { id: 'loops-templates', unit: '12. Loops and templates', title: 'FIND, REDUCE, APPLY and INVOKE', level: 'Advanced', minutes: 10,
      summary: 'Search and combine lists with FIND and REDUCE, run templates with APPLY and INVOKE, and give template inputs names.',
      steps: [
        { title: 'Find the first', sel: '#cmdInputBox', text: 'FIND outputs the first member that makes the template true. Type <code>show find [? > 10] [4 12 7 30]</code>.', check: { command: '\\bfind\\b' } },
        { title: 'Combine them all', sel: '#cmdInputBox', text: 'REDUCE combines all the members, two at a time, into one answer. The template has two blanks, <code>?1</code> and <code>?2</code>. Try <code>show reduce "sum [1 2 3 4 5]</code> and <code>show reduce [word ?1 ?2] [a b c]</code>.', check: { command: '\\breduce\\b' } },
        { title: 'The biggest', sel: '#cmdInputBox', text: 'The template can be any expression that outputs. This one keeps the bigger of two numbers, so REDUCE finds the biggest: <code>show reduce [ifelse ?1 > ?2 [?1] [?2]] [3 9 4 7]</code>.', check: { command: '\\breduce\\s*\\[\\s*ifelse' } },
        { title: 'APPLY and INVOKE', sel: '#cmdInputBox', text: 'APPLY runs a template with its inputs in a list: <code>show apply "sum [3 4]</code>. INVOKE takes the inputs one by one: <code>show invoke "uppercase "hello</code>. For more than one input, wrap INVOKE in parentheses: <code>show (invoke "sum 1 2 3)</code>.', check: { command: '\\b(apply|invoke)\\b' } },
        { title: 'Templates with names', sel: '#cmdInputBox', text: 'Instead of <code>?</code>, a template can name its inputs. Put the names in a list at the front: <code>[[x] :x * :x]</code> means "take x and output x times x". Type <code>show map [[x] :x * :x] [1 2 3 4]</code>.', check: { command: '\\[\\s*\\[\\s*\\w+' } },
        { title: 'Two names', sel: '#cmdInputBox', text: 'MAP can walk along two lists at once (in parentheses). Type <code>show (map [[a b] word :a :b] [sun moon] [shine light])</code>.', check: { command: '\\(\\s*map\\b' } },
        { title: 'Templates as inputs', sel: '#editorCard', text: 'Your own procedures can take templates too. TWICE runs a template on its input, then again on the answer. Run it.', code: 'to twice :tmpl :x\n  output invoke :tmpl invoke :tmpl :x\nend\n\nshow twice [[n] :n * 3] 5\nshow twice "butfirst "turtle\nshow twice [[w] word :w "!] "hey\n', check: { output: '45' } },
        { title: 'Challenge: COUNT.IF', sel: '#editorCard', text: 'Add a procedure <code>count.if :tmpl :list</code> that outputs how many members make the template true, and run the program. Then try <code>show count.if [? > 2] [1 5 3 0]</code> in the command center.', check: { defined: 'count.if' }, hint: '<pre>to count.if :tmpl :list\n  output count filter :tmpl :list\nend</pre>' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>reduce [word ?1 ?2] [a b c]</code> output?', options: ['abc', '[a b c]', 'a'], answer: 0, explain: 'REDUCE glues the members together two at a time.' } },
        { title: 'One more', quiz: { q: 'What does <code>invoke [[x] :x + 1] 9</code> output?', options: ['10', '9', '[10]'], answer: 0, explain: 'The template names its input x, and outputs x + 1.' } },
      ] },

    // ---- 13. Talking to the program ------------------------------------------------------------
    { id: 'talk-print', unit: '13. Talking to the program', title: 'PRINT, TYPE and SHOW', level: 'Everyone', minutes: 7,
      summary: 'Three ways to put text in the command center, and when to use each.',
      steps: [
        { title: 'PRINT', sel: '#cmdInputBox', text: 'Type <code>print [a [b c] d]</code>. PRINT leaves off the outer brackets of a list, keeps the inner ones, and starts a new line at the end.', check: { command: '^\\s*(print|pr)\\s*\\[' } },
        { title: 'SHOW', sel: '#cmdInputBox', text: 'Now type <code>show [a [b c] d]</code>. SHOW keeps the outer brackets, so you can tell a list from a word. Use it when you want to see exactly what something is.', check: { command: '^\\s*show\\s*\\[' } },
        { title: 'TYPE', sel: '#editorCard', text: 'TYPE is like PRINT but does not start a new line, so the next thing goes on the same line. A word in vertical bars can contain spaces. Run it.', code: 'type "|Score: |\nprint 10\ntype "Loading\nrepeat 5 [type ".]\nprint "done\n', check: { output: 'Loading\\.\\.\\.\\.\\.done' } },
        { title: 'Several things at once', sel: '#cmdInputBox', text: 'Wrap PRINT, SHOW or TYPE in parentheses to give it more than one input. Type <code>(print "x "= 10)</code>.', check: { command: '^\\s*\\(\\s*(print|pr|show|type)\\b' } },
        { title: 'A neat table', sel: '#editorCard', text: '<code>char 9</code> is the tab character, which lines things up in columns. Run it.', code: 'print [number square cube]\nfor [i 1 5] [\n  type :i type char 9\n  type :i * :i type char 9\n  print :i * :i * :i\n]\n', check: { output: '125' } },
        { title: 'Quick quiz', quiz: { q: 'Which one shows <code>[1 2]</code> with the brackets?', options: ['show [1 2]', 'print [1 2]', 'type [1 2]'], answer: 0, explain: 'Only SHOW keeps the outer brackets.' } },
        { title: 'One more', quiz: { q: 'What is the difference between TYPE and PRINT?', options: ['TYPE does not start a new line afterwards', 'TYPE prints in bigger letters', 'TYPE only works with numbers'], answer: 0, explain: 'TYPE leaves the cursor at the end of the line.' } },
      ] },

    { id: 'talk-quiz', unit: '13. Talking to the program', title: 'READWORD, READLIST and a quiz game', level: 'Everyone', minutes: 10,
      summary: 'Ask the player questions with READWORD and READLIST and build a quiz game.',
      steps: [
        { title: 'Programs that ask', text: 'READWORD and READLIST wait for someone to type a line in the command center and press <kbd>Enter</kbd>. READWORD outputs the whole line as one word. READLIST outputs it as a list of words.' },
        { title: 'What is your name?', sel: '#editorCard', text: 'Run this. When it asks, type your name in the command center and press <kbd>Enter</kbd>.', code: 'print [What is your name?]\nmake "name readlist\nprint sentence [Hello,] :name\nprint sentence [Your first name has] count first :name\n', check: { run: true }, hint: 'The program waits until you type something in the command center box under the turtle world.' },
        { title: 'Why a list?', text: 'READLIST gave a list, so if you typed two names, <code>first :name</code> is just the first one. With READWORD, "Ada Lovelace" would be one word with a space inside.' },
        { title: 'A quiz game', sel: '#editorCard', text: 'QUESTION asks one question and checks the answer. The score is kept in a variable. Run it and play.', code: 'to question :q :answer\n  print :q\n  make "reply readword\n  ifelse :reply = :answer [\n    print [Right!]\n    make "score :score + 1\n  ] [\n    print sentence [Not quite. It is] :answer\n  ]\nend\n\nto quiz\n  make "score 0\n  question [What is 7 times 8?] 56\n  question [What do blue and yellow make?] "green\n  question [How many legs does a spider have?] 8\n  print (sentence [You got] :score [out of 3.])\nend\n\nquiz\n', check: { output: 'you got' } },
        { title: 'Numbers are words too', text: 'You typed 56 and READWORD gave the word 56. That is fine: Logo compares numbers by value, so <code>"56 = 56</code> is true.' },
        { title: 'Add a question', sel: '#editorCard', text: 'Add a fourth QUESTION line of your own to QUIZ, and change "out of 3" to "out of 4".', check: { codeHas: '(question\\s*\\[[\\s\\S]*){4}' }, hint: 'For example: <code>question [What is the capital of France?] "Paris</code>' },
        { title: 'Play again', sel: '#tbRun', text: 'Run it and play your new quiz.', check: { output: 'you got' } },
        { title: 'Quick quiz', quiz: { q: 'You type <code>big red dog</code>. What does READLIST output?', options: ['[big red dog]', 'big red dog as one word', 'big'], answer: 0, explain: 'READLIST splits the line into a list of words.' } },
      ] },

    { id: 'talk-keys', unit: '13. Talking to the program', title: 'Keys: READCHAR and KEYP', level: 'Everyone', minutes: 10,
      summary: 'Drive the turtle with the arrow keys using READCHAR and KEYP.',
      steps: [
        { title: 'One key at a time', text: 'READCHAR waits for one key and outputs it. The keys go to the <b>turtle world</b>, so click on the turtle world first. The arrow keys come back as the words LEFT, RIGHT, UP and DOWN.' },
        { title: 'A remote control', sel: '#editorCard', text: 'DRIVE waits for a key, moves the turtle, and waits again. The q key stops it. Run it, then <b>click the turtle world</b> and press the arrow keys.', code: 'to drive\n  print [Click the turtle world. Arrow keys move, q quits.]\n  repeat 500 [\n    make "key readchar\n    if :key = "q [print [Bye.] stop]\n    if :key = "UP [forward 20]\n    if :key = "DOWN [back 20]\n    if :key = "LEFT [left 30]\n    if :key = "RIGHT [right 30]\n  ]\nend\n\nclearscreen\ndrive\n', check: { drawn: 3 }, hint: 'Press F5 first, then click in the turtle world so it gets your keys.' },
        { title: 'Done driving', sel: '#worldCard', text: 'Press <kbd>q</kbd> in the turtle world to finish.', check: { output: 'bye' } },
        { title: 'Waiting is a problem', text: 'READCHAR waits. While it waits, nothing else happens. In a game, things need to keep moving even when nobody presses a key. That is what KEYP is for: it says <b>true</b> if a key is waiting, without waiting itself.' },
        { title: 'Keep moving', sel: '#editorCard', text: 'Now the turtle moves all the time and the arrow keys steer it. STEER only reads a key if one is waiting. WRAP makes the turtle come back on the other side when it leaves the screen. Run it, click the turtle world, and steer for 20 seconds.', code: 'to steer\n  if not keyp [stop]\n  make "key readchar\n  if :key = "LEFT [left 30]\n  if :key = "RIGHT [right 30]\nend\n\nto cruise\n  repeat 1200 [\n    steer\n    forward 2\n    wait 1\n  ]\nend\n\nclearscreen wrap\nprint [Click the turtle world and steer with the left and right arrows.]\ncruise\n', check: { drawn: 100 } },
        { title: 'The game loop', text: 'CRUISE is a <b>game loop</b>: check the keys, move things, wait a moment, again and again. <code>wait 1</code> waits a sixtieth of a second, so the loop runs about 60 times a second. Almost every game works this way.' },
        { title: 'Challenge: change color', sel: '#editorCard', text: 'Add a line to STEER so that the <kbd>c</kbd> key changes the pen color, for example <code>if :key = "c [setpencolor random 16]</code>. Then run it and try it.', check: { codeHas: 'if\\s+:key\\s*=\\s*"c\\b' } },
        { title: 'Quick quiz', quiz: { q: 'Why must you click the turtle world before pressing keys?', options: ['Keys go to the part of the screen you clicked last, and the program reads them from the turtle world', 'To start the program', 'Clicking makes the turtle faster'], answer: 0, explain: 'If the editor or the command center has the focus, the keys go there instead.' } },
        { title: 'One more', quiz: { q: 'What does KEYP do?', options: ['Says whether a key is waiting, without waiting', 'Waits for a key and outputs it', 'Presses a key'], answer: 0, explain: 'READCHAR waits and outputs the key. KEYP just checks.' } },
      ] },

    { id: 'talk-mouse-timers', unit: '13. Talking to the program', title: 'The mouse and timers', level: 'Intermediate', minutes: 10,
      summary: 'Follow the mouse with MOUSEPOS, react to clicks with MOUSEON, and run things on a timer with SETTIMER and WAIT.',
      steps: [
        { title: 'Where is the mouse?', sel: '#editorCard', text: 'MOUSEPOS outputs the mouse position in the turtle world as a list [x y]. TOWARDS gives the heading to a position. Together: a turtle that chases the mouse. Run it and move the mouse over the turtle world.', code: 'clearscreen\nrepeat 600 [\n  setheading towards mousepos\n  if (distance mousepos) > 5 [forward 3]\n  wait 1\n]\n', check: { drawn: 10 } },
        { title: 'Clicks', sel: '#editorCard', text: 'MOUSEON takes five lists of instructions: for the left button going down, the left button coming up, the right button down, the right button up, and the mouse moving. Empty lists mean "do nothing". Run this.', code: 'clearscreen\nsetpensize 3\nmouseon [setpos mousepos] [] [clean] [] []\nprint [Click in the turtle world to draw. Right-click to clean up.]\n', check: { run: true } },
        { title: 'Draw with clicks', sel: '#worldCard', text: 'Click in the turtle world in a few places. The turtle draws a line to each click. Notice the program already finished, but Logo still listens to the mouse.', check: { drawn: 3 } },
        { title: 'Stop listening', sel: '#cmdInputBox', text: 'Type <code>mouseoff</code> so that clicks do nothing again.', check: { command: '\\bmouseoff\\b' } },
        { title: 'WAIT', sel: '#cmdInputBox', text: 'WAIT pauses for a number of sixtieths of a second, so <code>wait 60</code> is one second. Type <code>repeat 6 [forward 30 right 60 wait 30]</code> and watch.', check: { command: '\\bwait\\s+\\d' } },
        { title: 'Timers', sel: '#editorCard', text: 'SETTIMER runs a list of instructions again and again in the background. Its inputs are a timer number, the time between runs in <b>milliseconds</b> (1000 is one second), and the list. CLEARTIMER stops it. Run this and wait five seconds.', code: 'make "secs 0\nsettimer 1 1000 [\n  make "secs :secs + 1\n  print :secs\n  if :secs = 5 [cleartimer 1 print [Time is up!]]\n]\nprint [The timer is ticking...]\n', check: { output: 'time is up' } },
        { title: 'Remember to clear', text: 'Like MOUSEON, a timer keeps going after the program ends, until CLEARTIMER stops it. Running a program again with <kbd>F5</kbd> also clears every timer and turns off the mouse.' },
        { title: 'Quick quiz', quiz: { q: 'In <code>mouseon [a] [b] [c] [d] [e]</code>, when does [e] run?', options: ['When the mouse moves', 'When the left button goes down', 'When the right button comes up'], answer: 0, explain: 'The five lists are: left down, left up, right down, right up, move.' } },
        { title: 'One more', quiz: { q: 'How often does <code>settimer 2 500 [fd 10]</code> move the turtle?', options: ['Twice a second', 'Every 500 seconds', 'Once'], answer: 0, explain: '500 milliseconds is half a second.' } },
      ] },

    // ---- 14. Keeping data ----------------------------------------------------------------------
    { id: 'data-arrays', unit: '14. Keeping data', title: 'Arrays', level: 'Intermediate', minutes: 9,
      summary: 'Store numbered values in arrays, change them with SETITEM, and write arrays with curly braces.',
      steps: [
        { title: 'A row of boxes', sel: '#cmdInputBox', text: 'An <b>array</b> is a row of numbered boxes. Unlike a list, you can change what is in a box. Type <code>make "box array 5 show :box</code>. The five boxes start empty, and arrays show in curly braces.', check: { command: '\\barray\\s+\\d' } },
        { title: 'Put something in', sel: '#cmdInputBox', text: 'SETITEM puts a value in a box: first the box number, then the array, then the value. Type <code>setitem 2 :box "hat show :box</code>.', check: { command: '\\bsetitem\\b' } },
        { title: 'Take it out', sel: '#cmdInputBox', text: 'ITEM reads a box, just like with lists: <code>print item 2 :box</code>.', check: { command: '\\bitem\\s+\\d' } },
        { title: 'Curly braces', sel: '#cmdInputBox', text: 'You can write an array directly in curly braces: <code>make "days {mon tue wed thu fri} print item 3 :days</code>.', check: { command: '\\{' } },
        { title: 'Filling an array', sel: '#editorCard', text: 'FOR is a good way to fill an array. Run it.', code: 'make "squares array 10\nfor [i 1 10] [setitem :i :squares :i * :i]\nshow :squares\nprint item 7 :squares\n', check: { output: '49' } },
        { title: 'Counting dice', sel: '#editorCard', text: 'Here each box counts how often a number came up when rolling a die 600 times. Then the turtle draws a bar for each. Run it a few times.', code: 'make "rolls array 6\nfor [i 1 6] [setitem :i :rolls 0]\nrepeat 600 [\n  make "r 1 + random 6\n  setitem :r :rolls 1 + item :r :rolls\n]\nshow :rolls\n\nclearscreen hideturtle\nsetpensize 30\nfor [i 1 6] [\n  penup setxy :i * 60 - 210 -200 setheading 0 pendown\n  forward 2 * item :i :rolls\n]\n', check: { drawn: 6 } },
        { title: 'Arrays or lists?', text: 'Lists grow and shrink and are built with FPUT and SENTENCE. Arrays have a fixed size, and SETITEM changes them in place, which is fast. LISTTOARRAY and ARRAYTOLIST convert from one to the other.' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>item 1 {a b c}</code> output?', options: ['a', 'b', '{a}'], answer: 0, explain: 'Arrays count from 1, like lists.' } },
        { title: 'One more', quiz: { q: 'Which can be changed in place with SETITEM?', options: ['An array', 'A list', 'A word'], answer: 0, explain: 'Lists and words are never changed; you build new ones instead.' } },
      ] },

    { id: 'data-plists', unit: '14. Keeping data', title: 'Property lists', level: 'Intermediate', minutes: 8,
      summary: 'Attach named properties to a name with PPROP, read them with GPROP, and list them with PLIST.',
      steps: [
        { title: 'Facts about a name', sel: '#cmdInputBox', text: 'A <b>property list</b> keeps facts about a name. PPROP takes the name, the property and the value. Type <code>pprop "rex "kind "dog pprop "rex "legs 4</code>.', check: { command: '\\bpprop\\b' } },
        { title: 'Get a property', sel: '#cmdInputBox', text: 'GPROP gets one back. Type <code>print gprop "rex "legs</code>.', check: { command: '\\bgprop\\b' } },
        { title: 'All of them', sel: '#cmdInputBox', text: 'PLIST shows everything as a list of pairs. Type <code>show plist "rex</code>.', check: { command: '\\bplist\\b' } },
        { title: 'An animal book', sel: '#editorCard', text: 'FOREACH fills in the properties for three animals from a list of facts. DESCRIBE reads them back. Run it.', code: 'foreach [[dog 4 woof] [bird 2 tweet] [snake 0 hiss]] [\n  pprop first ? "legs item 2 ?\n  pprop first ? "sound last ?\n]\n\nto describe :animal\n  print (sentence "The :animal [has] gprop :animal "legs [legs and says] gprop :animal "sound)\nend\n\ndescribe "dog\ndescribe "snake\n', check: { output: 'says hiss' } },
        { title: 'Missing properties', sel: '#cmdInputBox', text: 'Asking for a property that was never set gives the empty list. Type <code>show gprop "dog "color</code>. REMPROP removes a property again.', check: { command: '\\bgprop\\b' } },
        { title: 'Add an animal', sel: '#editorCard', text: 'Add a cat to the list of facts and a line <code>describe "cat</code> at the end. Run it.', check: { codeHas: 'describe\\s+"cat' }, hint: 'Add <code>[cat 4 meow]</code> inside the big list of facts.' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>gprop "rex "kind</code> output after <code>pprop "rex "kind "dog</code>?', options: ['dog', 'rex', '[kind dog]'], answer: 0, explain: 'GPROP gives the value of one property.' } },
      ] },

    { id: 'data-stacks', unit: '14. Keeping data', title: 'Stacks and queues', level: 'Intermediate', minutes: 9,
      summary: 'Keep things in order with PUSH and POP (last in, first out) and QUEUE and DEQUEUE (first in, first out).',
      steps: [
        { title: 'A stack of plates', sel: '#cmdInputBox', text: 'A <b>stack</b> is like a pile of plates: you put plates on top and take them off the top. PUSH adds to a list in a variable, POP takes the newest one off and outputs it. Type <code>push "plates "red push "plates "blue show :plates</code>.', check: { command: '\\bpush\\b' } },
        { title: 'Pop', sel: '#cmdInputBox', text: 'Type <code>print pop "plates</code>. You get blue, the last one pushed. Last in, first out. Notice that PUSH and POP take the variable <i>name</i>, with a quote.', check: { command: '\\bpop\\b' } },
        { title: 'A queue', sel: '#cmdInputBox', text: 'A <b>queue</b> is like a line at a shop: first in, first out. Type <code>queue "line "ann queue "line "bob print dequeue "line</code>.', check: { command: '\\bdequeue\\b' } },
        { title: 'An undo button', sel: '#editorCard', text: 'Every WALK pushes its move on a stack. UNDO pops the last move and walks it back with the eraser pen. Run it: two of the three lines are drawn, the third is undone.', code: 'make "moves []\n\nto walk :d :a\n  push "moves (list :d :a)\n  forward :d right :a\nend\n\nto undo\n  if emptyp :moves [print [Nothing to undo.] stop]\n  make "m pop "moves\n  left last :m\n  penerase back first :m penpaint\nend\n\nclearscreen\nwalk 100 90\nwalk 50 90\nwalk 80 45\nundo\n', check: { run: true } },
        { title: 'Undo some more', sel: '#cmdInputBox', text: 'Type <code>undo</code> a few times in the command center, or <code>walk 60 120</code> to make new moves.', check: { command: '^\\s*undo\\b' } },
        { title: 'Taking turns', sel: '#editorCard', text: 'A queue is right for taking turns. Run it.', code: 'make "line []\nqueue "line "Ana\nqueue "line "Ben\nqueue "line "Cy\nuntil [emptyp :line] [print sentence dequeue "line [is up next.]]\n', check: { output: 'cy is up next' } },
        { title: 'Quick quiz', quiz: { q: 'You PUSH a, then b, then c. What does POP give?', options: ['c', 'a', 'b'], answer: 0, explain: 'A stack gives back the newest first.' } },
        { title: 'One more', quiz: { q: 'You QUEUE a, then b, then c. What does DEQUEUE give?', options: ['a', 'c', 'b'], answer: 0, explain: 'A queue gives back the oldest first.' } },
      ] },

    { id: 'data-files', unit: '14. Keeping data', title: 'Saving to files', level: 'Intermediate', minutes: 10,
      summary: 'Write lines to a file with OPENWRITE, SETWRITE and PRINT, and read them back with OPENREAD, READLIST and EOFP.',
      steps: [
        { title: 'Data that lasts', text: 'Variables are forgotten when a program starts fresh. <b>Files</b> stay. Your files are kept in this browser in the <b>/projects</b> folder, so a program can save something today and read it tomorrow.' },
        { title: 'Write a file', sel: '#editorCard', text: 'OPENWRITE opens a file for writing (a new, empty one). SETWRITE sends everything PRINT prints into that file instead of the screen. SETWRITE [] sends printing back to the screen, and CLOSE finishes the file. Run it.', code: 'make "file "/projects/pets.txt\nopenwrite :file\nsetwrite :file\nprint [cat Tom 3]\nprint [dog Rex 5]\nprint [fish Bubbles 1]\nsetwrite []\nclose :file\nprint [Saved.]\n', check: { output: 'saved' } },
        { title: 'Find the file', sel: '#railFiles', text: 'Open <b>Files</b> and look in <b>/projects</b>. There is pets.txt. Click it to see the three lines inside.' },
        { title: 'Read it back', sel: '#editorCard', text: 'OPENREAD opens the file and SETREAD makes READLIST read from it instead of the keyboard. EOFP ("end of file?") says when there are no more lines. FILEP checks first that the file is there. Run it.', code: 'make "file "/projects/pets.txt\n\nto read.pets\n  if not filep :file [print [There is no file yet. Run the program from the last step first.] stop]\n  openread :file\n  setread :file\n  while [not eofp] [\n    make "line readlist\n    print (sentence item 2 :line [the] first :line [is] last :line)\n  ]\n  setread []\n  close :file\nend\n\nread.pets\n', check: { output: 'tom the cat is 3' } },
        { title: 'Does it exist?', sel: '#cmdInputBox', text: 'FILEP tells whether a file exists. Type <code>show filep "/projects/pets.txt</code>. A program can use it to check before reading.', check: { command: '\\bfilep\\b' } },
        { title: 'Adding to the end', text: 'OPENWRITE empties the file first. To add lines at the end instead, use OPENAPPEND in its place. The <b>diary</b> example does exactly that.' },
        { title: 'Quick quiz', quiz: { q: 'What does <code>setwrite []</code> do?', options: ['Sends PRINT back to the screen', 'Deletes the file', 'Writes an empty line'], answer: 0, explain: 'The empty list means "the screen".' } },
        { title: 'One more', quiz: { q: 'Why does the reading loop use <code>while [not eofp]</code>?', options: ['To stop when there are no more lines to read', 'To skip the first line', 'To make the file empty'], answer: 0, explain: 'EOFP is true at the end of the file.' } },
      ] },

    { id: 'data-files-tour', unit: '14. Keeping data', title: 'Your files and sharing', level: 'Everyone', minutes: 4,
      summary: 'A short tour of where your programs live, how to bring files in, and how to share a program as a link.', tour: 'files' },

    // ---- 15. Power tools -----------------------------------------------------------------------
    { id: 'power-run', unit: '15. Power tools', title: 'Programs that build programs', level: 'Advanced', minutes: 10,
      summary: 'Run lists as instructions with RUN and RUNRESULT, and make new procedures with DEFINE and read them with TEXT.',
      steps: [
        { title: 'Instructions are lists', text: 'In Logo, a list of instructions is just a list, like any other. So a program can <b>make</b> a list of instructions and then run it. That is the job of RUN.' },
        { title: 'RUN', sel: '#cmdInputBox', text: 'Type <code>run [repeat 5 [forward 80 right 144]]</code>.', check: { command: '\\brun\\s*\\[' } },
        { title: 'RUN can output', sel: '#cmdInputBox', text: 'If the instructions output something, so does RUN. Type <code>print run [3 + 4]</code>.', check: { command: '\\brun\\b' } },
        { title: 'Building instructions', sel: '#editorCard', text: 'POLYGON.PROGRAM does not draw anything. It <i>outputs a program</i> that draws. SHOW shows the program, RUN runs it. Run this.', code: 'to polygon.program :n :size\n  output (list "repeat :n (list "forward :size "right 360 / :n))\nend\n\nshow polygon.program 5 80\nclearscreen\nrun polygon.program 5 80\nrun polygon.program 8 40\n', check: { drawn: 10 } },
        { title: 'RUNRESULT', sel: '#cmdInputBox', text: 'RUNRESULT runs a list and tells you whether it output something: a list with the answer in it, or the empty list. Try <code>show runresult [sum 2 3]</code> and <code>show runresult [print "hi]</code>.', check: { command: '\\brunresult\\b' } },
        { title: 'DEFINE', sel: '#editorCard', text: 'DEFINE makes a procedure from a list: first the list of inputs, then one list for each line. This program defines SHAPE3, SHAPE4, SHAPE5 and SHAPE6 all at once. Run it.', code: 'foreach [3 4 5 6] [\n  define word "shape ? (list [size] (list "repeat ? (list "forward ":size "right 360 / ?)))\n]\n\nclearscreen\nshape5 80\n', check: { drawn: 5 } },
        { title: 'TEXT', sel: '#cmdInputBox', text: 'TEXT outputs a procedure in the same form DEFINE takes. Type <code>show text "shape6</code>, and then try <code>shape6 50</code>.', check: { command: '\\btext\\b' } },
        { title: 'Quick quiz', quiz: { q: 'What does <code>run list "forward 50</code> do?', options: ['Moves the turtle forward 50', 'Prints [forward 50]', 'Nothing'], answer: 0, explain: 'LIST builds the list [forward 50], and RUN runs it.' } },
        { title: 'One more', quiz: { q: 'In <code>define "double [[x] [output :x * 2]]</code>, what is <code>[x]</code>?', options: ['The list of inputs', 'The first line', 'The name of the procedure'], answer: 0, explain: 'First the inputs, then one list per line.' } },
      ] },

    { id: 'power-catch', unit: '15. Power tools', title: 'CATCH, THROW and ERROR', level: 'Advanced', minutes: 9,
      summary: 'Jump out of deep inside a program with THROW, and handle errors with CATCH "ERROR.',
      steps: [
        { title: 'Escape hatch', text: 'THROW jumps straight out of whatever is running, through any number of procedures and loops, back to the CATCH with the same tag. To carry a value along, put THROW in parentheses: <code>(throw "found 42)</code>.' },
        { title: 'Found it', sel: '#editorCard', text: 'FIRST.EVEN looks through a list and throws the first even number it finds. If none turns up it outputs "none. Run it.', code: 'to first.even :list\n  foreach :list [if 0 = remainder ? 2 [(throw "found ?)]]\n  output "none\nend\n\nshow catch "found [first.even [3 7 8 5]]\nshow catch "found [first.even [3 7]]\n', check: { output: 'none' } },
        { title: 'What happened', text: 'The first time, THROW jumped out of the FOREACH and out of FIRST.EVEN, and CATCH output the 8. The second time nothing was thrown, so CATCH output what FIRST.EVEN output.' },
        { title: 'Catching errors', sel: '#editorCard', text: 'The tag "error is special: CATCH "error catches Logo errors. Afterwards ERROR outputs a list describing the error: its number, the message, the procedure, and the line. Run it.', code: 'to safe.divide :a :b\n  catch "error [output :a / :b]\n  print sentence [Oops:] item 2 error\n  output 0\nend\n\nprint safe.divide 10 2\nprint safe.divide 10 0\n', check: { output: 'oops' } },
        { title: 'Try it', sel: '#cmdInputBox', text: 'Type <code>catch "error [forward "far] show error</code>. The error is caught, so the program could carry on.', check: { command: '\\bcatch\\s+"error\\b' } },
        { title: 'Stopping everything', text: '<code>throw "toplevel</code> stops the whole program from anywhere, like the Stop button. The <b>snake</b> example uses it when the snake crashes.' },
        { title: 'Quick quiz', quiz: { q: 'Why is <code>(throw "found ?)</code> in parentheses?', options: ['THROW takes one input unless it is in parentheses, and here it has two', 'Parentheses make it faster', 'Because of the question mark'], answer: 0, explain: 'With parentheses THROW can carry a value to the CATCH.' } },
        { title: 'One more', quiz: { q: 'What does <code>catch "error [...]</code> catch?', options: ['Logo errors inside the list', 'Only THROW "error', 'Nothing, it is a mistake'], answer: 0, explain: 'Afterwards, ERROR tells you what went wrong.' } },
      ] },

    { id: 'power-macros', unit: '15. Power tools', title: 'Macros and backquote', level: 'Advanced', minutes: 10,
      summary: 'Write macros with .MACRO that output instructions to run in the caller\'s place, using backquote to build them.',
      steps: [
        { title: 'Procedures that write code', text: 'A <b>macro</b> is a procedure that outputs a list of instructions. Logo then runs those instructions as if they had been written right where the macro was used. You define one with <code>.macro</code> instead of <code>to</code>.' },
        { title: 'TWICE', sel: '#editorCard', text: 'TWICE outputs its list twice, joined together, and Logo runs the result. Run it.', code: '.macro twice :commands\n  output (sentence :commands :commands)\nend\n\ntwice [print "hello]\nshow macroexpand [twice [print "hello]]\n', check: { output: 'hello' } },
        { title: 'Backquote', sel: '#cmdInputBox', text: 'Building instructions with LIST and SENTENCE gets messy. A <b>backquote</b> <code>`</code> in front of a list copies it, but a comma inserts a value. Type <code>make "x 5 show `[x is ,:x and the sum is ,[sum 2 3]]</code>.', check: { command: '`' } },
        { title: 'Splicing', sel: '#cmdInputBox', text: 'Comma-at, <code>,@</code>, inserts the members of a list instead of the list itself. Type <code>make "more [b c] show `[a ,:more d]</code> and then <code>show `[a ,@:more d]</code>.', check: { command: ',@' } },
        { title: 'UNLESS', sel: '#editorCard', text: 'UNLESS runs its instructions when the condition is <i>false</i>. The macro builds an IF instruction with backquote. Run it.', code: '.macro unless :condition :body\n  output `[if not run ,:condition ,:body]\nend\n\nto check.age :age\n  unless [:age > 0] [print [That is not an age.] stop]\n  print sentence [You are] :age\nend\n\ncheck.age 9\ncheck.age -3\nshow macroexpand [unless [:n > 10] [print "small]]\n', check: { output: 'not an age' } },
        { title: 'Why a macro?', text: 'Look at the STOP inside UNLESS. Because UNLESS is a macro, the IF it builds runs <i>inside CHECK.AGE</i>, so STOP stops CHECK.AGE. If UNLESS were an ordinary procedure, STOP would only stop UNLESS, and CHECK.AGE would carry on and print "You are -3".' },
        { title: 'Try it', sel: '#cmdInputBox', text: 'Type <code>check.age 0</code> and <code>check.age 12</code>.', check: { command: '\\bcheck\\.age\\b' } },
        { title: 'Quick quiz', quiz: { q: 'What does <code>show `[a ,:x]</code> show when <code>:x</code> is 7?', options: ['[a 7]', '[a ,:x]', '[a x]'], answer: 0, explain: 'The comma puts the value of :x into the copy.' } },
        { title: 'One more', quiz: { q: 'What does a macro output?', options: ['Instructions that Logo then runs in the place where the macro was used', 'A number', 'Nothing'], answer: 0, explain: 'MACROEXPAND shows you those instructions without running them.' } },
      ] },

    { id: 'power-turtles', unit: '15. Power tools', title: 'Many turtles, and sound', level: 'Intermediate', minutes: 10,
      summary: 'Command a team of turtles with TELL, ASK, EACH and SETTURTLE, and make sounds with TONE and SOUND.',
      steps: [
        { title: 'More turtles', sel: '#cmdInputBox', text: 'There is more than one turtle. They are numbered from 0, and turtle 0 is the one you have been using. TELL says which turtles listen. Type <code>clearscreen tell [0 1 2 3]</code>.', check: { command: '\\btell\\b' } },
        { title: 'EACH', sel: '#cmdInputBox', text: 'Now every command goes to all four, so they would draw on top of each other. EACH runs a list once for each turtle, and WHO says which one is running it. Type <code>each [setheading 90 * who]</code> and then <code>forward 100</code>.', check: { command: '\\beach\\b' } },
        { title: 'ASK', sel: '#cmdInputBox', text: 'ASK gives commands to some turtles just once, without changing who is listening. Type <code>ask 2 [setpencolor "red forward 50]</code>.', check: { command: '\\bask\\b' } },
        { title: 'SETTURTLE', sel: '#cmdInputBox', text: '<code>setturtle 1</code> picks a single turtle, the same as <code>tell 1</code>. Type <code>setturtle 1 right 45 forward 80</code>, then <code>show who</code>.', check: { command: '\\bsetturtle\\b' } },
        { title: 'A turtle race', sel: '#editorCard', text: 'Six turtles line up and each one takes random steps. ASK can also output a value, so <code>ask ? [xcor]</code> tells how far each one got. Run it.', code: 'clearscreen\ntell [0 1 2 3 4 5]\neach [penup setheading 90 setxy -350 150 - 60 * who pendown setpencolor who + 1]\nrepeat 100 [each [forward random 8] wait 1]\ntell 0\nmake "best 0\nforeach [1 2 3 4 5] [if (ask ? [xcor]) > (ask :best [xcor]) [make "best ?]]\nprint sentence [The winner is turtle] :best\n', check: { output: 'winner' } },
        { title: 'Sound', sel: '#cmdInputBox', text: 'TONE plays a note: the frequency in hertz and how long in milliseconds. Turn your sound on and type <code>tone 440 500</code>. Higher numbers are higher notes.', check: { command: '\\btone\\b' } },
        { title: 'A tune', sel: '#cmdInputBox', text: 'SOUND takes a list of pairs, frequency and milliseconds, and plays them one after another. Type <code>sound [262 200 330 200 392 400]</code>.', check: { command: '\\bsound\\b' } },
        { title: 'Challenge: a fanfare', sel: '#editorCard', text: 'Add a SOUND line at the end of the race program so the winner gets a fanfare, and run it.', check: { codeHas: '\\b(sound|tone)\\b' }, hint: '<code>sound [523 150 659 150 784 300]</code>' },
        { title: 'Quick quiz', quiz: { q: 'What is the difference between TELL and ASK?', options: ['TELL changes who listens from now on; ASK only for the instructions in its list', 'ASK is for questions only', 'There is none'], answer: 0, explain: 'After ASK, the same turtles as before are listening.' } },
      ] },

    // ---- 16. Capstone: Star Catcher ------------------------------------------------------------
    { id: 'capstone-catcher', unit: '16. Capstone: Star Catcher', title: 'Star Catcher 1: the catcher', level: 'Intermediate', minutes: 10,
      summary: 'Start a real game: a catcher at the bottom of the screen that moves with the arrow keys.',
      steps: [
        { title: 'The plan', text: 'In these four lessons you build a whole game, <b>Star Catcher</b>. Stars fall from the sky and you move a catcher left and right to catch them. Then we add scoring and lives, levels that get faster, and a high score saved in a file. Each lesson adds to the same program.' },
        { title: 'Part 1', sel: '#editorCard', text: 'Turtle 0 is the catcher: a blue square near the bottom, with its pen up so it leaves no trail. STEER reads a key only if one is waiting, and SETX moves the catcher sideways. PLAY runs a game loop for ten seconds. Read the program, then run it, click the turtle world, and use the left and right arrow keys.', code: '; STAR CATCHER, part 1: the catcher\n\nto setup\n  clearscreen\n  tell 0\n  penup setshape "square setpencolor "blue\n  setxy 0 -250\nend\n\nto steer\n  if not keyp [stop]\n  make "key readchar\n  if :key = "LEFT [setx xcor - 40]\n  if :key = "RIGHT [setx xcor + 40]\nend\n\nto play\n  setup\n  print [Click the turtle world, then press the left and right arrow keys.]\n  repeat 600 [steer wait 1]\n  print [Time is up.]\nend\n\nplay\n', check: { output: 'time is up' }, hint: 'Press F5, then click inside the turtle world so it gets the arrow keys.' },
        { title: 'How it fits together', text: 'SETUP gets everything ready, STEER handles the keys, and PLAY is the main loop. Small procedures with clear jobs make a game much easier to grow.' },
        { title: 'Keep it on the screen', sel: '#editorCard', text: 'Right now the catcher can slide off the edge. Add two lines at the end of STEER:<pre>if xcor < -360 [setx -360]\nif xcor > 360 [setx 360]</pre>', check: { codeHas: 'xcor\\s*<\\s*-\\s*3\\d\\d' }, hint: 'Put them just before the END of STEER.' },
        { title: 'Test it', sel: '#tbRun', text: 'Run it again and try to drive the catcher off the screen.', check: { run: true } },
        { title: 'Play from the command center', sel: '#cmdInputBox', text: 'The procedures stay defined, so you can type <code>play</code> to start again without the editor.', check: { command: '^\\s*play\\b' } },
        { title: 'Quick quiz', quiz: { q: 'Why does the catcher use <code>penup</code>?', options: ['So it moves without drawing a line', 'So it moves faster', 'So it can read keys'], answer: 0, explain: 'The catcher should move, not draw.' } },
      ] },

    { id: 'capstone-star', unit: '16. Capstone: Star Catcher', title: 'Star Catcher 2: a falling star', level: 'Intermediate', minutes: 10,
      summary: 'Add a second turtle as a falling star that starts again at the top when it reaches the bottom.',
      steps: [
        { title: 'A second turtle', text: 'The star will be <b>turtle 1</b>, in the shape of a star. The game loop will move it down a little each time round. When it falls past the bottom, it jumps back to the top at a random place.' },
        { title: 'Part 2', sel: '#editorCard', text: 'New in this part: SETUP also prepares turtle 1, NEW.STAR puts it at the top, FALL moves it down by <code>:speed</code>, and CHECK sends it back up when it reaches the bottom. <code>ask 1 [ycor]</code> asks the star for its height. Run it.', code: '; STAR CATCHER, part 2: a falling star\n\nto setup\n  clearscreen\n  make "speed 3\n  tell 1\n  penup setshape "star setpencolor "orange\n  tell 0\n  penup setshape "square setpencolor "blue\n  setxy 0 -250\n  new.star\nend\n\nto new.star\n  ask 1 [setxy (random 700) - 350 280]\nend\n\nto steer\n  if not keyp [stop]\n  make "key readchar\n  if :key = "LEFT [setx xcor - 40]\n  if :key = "RIGHT [setx xcor + 40]\n  if xcor < -360 [setx -360]\n  if xcor > 360 [setx 360]\nend\n\nto fall\n  ask 1 [sety ycor - :speed]\nend\n\nto check\n  if (ask 1 [ycor]) < -280 [new.star]\nend\n\nto play\n  setup\n  print [Click the turtle world, then press the left and right arrow keys.]\n  repeat 900 [steer fall check wait 1]\n  print [Time is up.]\nend\n\nplay\n', check: { output: 'time is up' } },
        { title: 'Why ASK?', text: 'The catcher, turtle 0, is the one listening to commands, so <code>setx</code> in STEER moves the catcher. ASK gives the star its instructions without changing that.' },
        { title: 'Faster stars', sel: '#editorCard', text: 'Change <code>make "speed 3</code> in SETUP to a bigger number, like 6. Then run it.', check: { codeHas: 'make\\s+"speed\\s+([4-9]|\\d\\d+)\\b' } },
        { title: 'Try it', sel: '#tbRun', text: 'Run the game with the faster star. Can you still get under it?', check: { run: true } },
        { title: 'Quick quiz', quiz: { q: 'What does <code>ask 1 [ycor]</code> output?', options: ['The height of turtle 1, the star', 'The height of the catcher', 'Nothing'], answer: 0, explain: 'ASK outputs whatever its instructions output.' } },
        { title: 'One more', quiz: { q: 'What does <code>(random 700) - 350</code> give?', options: ['A random x from -350 to 349', 'A number from 0 to 700', 'Always -350'], answer: 0, explain: 'RANDOM 700 is 0 to 699; subtracting 350 centers it.' } },
      ] },

    { id: 'capstone-score', unit: '16. Capstone: Star Catcher', title: 'Star Catcher 3: catching and scoring', level: 'Intermediate', minutes: 10,
      summary: 'Notice when the catcher reaches a star, keep score, lose lives on misses, and end the game.',
      steps: [
        { title: 'Rules', text: 'Now the game gets rules. When the star comes close to the catcher, that is a catch: one point. When it falls past the bottom, that is a miss: one life lost. With no lives left, the game is over.' },
        { title: 'Part 3', sel: '#editorCard', text: 'New in this part: CHECK asks the star for its position and uses DISTANCE to see if it is near the catcher. CAUGHT and MISSED keep the score and the lives. PLAY now loops UNTIL the lives run out. Run it and play.', code: '; STAR CATCHER, part 3: catching and scoring\n\nto setup\n  clearscreen\n  make "score 0\n  make "lives 3\n  make "speed 3\n  tell 1\n  penup setshape "star setpencolor "orange\n  tell 0\n  penup setshape "square setpencolor "blue\n  setxy 0 -250\n  new.star\nend\n\nto new.star\n  ask 1 [setxy (random 700) - 350 280]\nend\n\nto steer\n  if not keyp [stop]\n  make "key readchar\n  if :key = "LEFT [setx xcor - 40]\n  if :key = "RIGHT [setx xcor + 40]\n  if xcor < -360 [setx -360]\n  if xcor > 360 [setx 360]\nend\n\nto fall\n  ask 1 [sety ycor - :speed]\nend\n\nto check\n  make "star ask 1 [pos]\n  if (distance :star) < 30 [caught stop]\n  if (last :star) < -280 [missed]\nend\n\nto caught\n  make "score :score + 1\n  print sentence [Caught! Score:] :score\n  new.star\nend\n\nto missed\n  make "lives :lives - 1\n  print sentence [Missed! Lives left:] :lives\n  new.star\nend\n\nto play\n  setup\n  print [Click the turtle world, then press the left and right arrow keys.]\n  until [:lives = 0] [steer fall check wait 1]\n  print sentence [Game over. Your score:] :score\nend\n\nplay\n', check: { output: 'game over' } },
        { title: 'Distance', text: '<code>distance :star</code> is how far the catcher (the turtle that is listening) is from the star\'s position. Under 30 steps counts as a catch. The <code>stop</code> after CAUGHT makes sure a caught star cannot also count as a miss.' },
        { title: 'More lives', sel: '#editorCard', text: 'The game is a bit hard. Change SETUP so you start with 5 lives.', check: { codeHas: 'make\\s+"lives\\s+5\\b' } },
        { title: 'Play again', sel: '#tbRun', text: 'Run it and see how many stars you can catch.', check: { output: 'game over' } },
        { title: 'Quick quiz', quiz: { q: 'Why does CHECK say <code>[caught stop]</code> and not just <code>[caught]</code>?', options: ['So that after a catch the miss test is skipped this time round', 'STOP ends the whole game', 'CAUGHT needs STOP to work'], answer: 0, explain: 'STOP ends CHECK only. The game loop goes on.' } },
      ] },

    { id: 'capstone-levels', unit: '16. Capstone: Star Catcher', title: 'Star Catcher 4: levels and a high score', level: 'Intermediate', minutes: 12,
      summary: 'Finish the game: faster levels with a fanfare, and a high score that is saved in a file.',
      steps: [
        { title: 'Finishing touches', text: 'Two more things make it a real game. Every five stars you go up a <b>level</b> and the stars fall faster. And the best score is <b>saved in a file</b>, so it is still there next time.' },
        { title: 'The whole game', sel: '#editorCard', text: 'New in this part: LEVEL.UP, called from CAUGHT every fifth star, and HIGH.SCORE, called at the end of PLAY. There are sounds too. Run it and play a full game.', code: '; STAR CATCHER - catch the falling stars with the arrow keys\n\nto setup\n  clearscreen\n  make "score 0\n  make "lives 3\n  make "level 1\n  make "speed 3\n  tell 1\n  penup setshape "star setpencolor "orange\n  tell 0\n  penup setshape "square setpencolor "blue\n  setxy 0 -250\n  new.star\nend\n\nto new.star\n  ask 1 [setxy (random 700) - 350 280]\nend\n\nto steer\n  if not keyp [stop]\n  make "key readchar\n  if :key = "LEFT [setx xcor - 40]\n  if :key = "RIGHT [setx xcor + 40]\n  if xcor < -360 [setx -360]\n  if xcor > 360 [setx 360]\nend\n\nto fall\n  ask 1 [sety ycor - :speed]\nend\n\nto check\n  make "star ask 1 [pos]\n  if (distance :star) < 30 [caught stop]\n  if (last :star) < -280 [missed]\nend\n\nto caught\n  make "score :score + 1\n  print sentence [Caught! Score:] :score\n  tone 660 50\n  if 0 = remainder :score 5 [level.up]\n  new.star\nend\n\nto missed\n  make "lives :lives - 1\n  print sentence [Missed! Lives left:] :lives\n  tone 150 200\n  new.star\nend\n\nto level.up\n  make "level :level + 1\n  make "speed :speed + 1\n  print sentence [Level] :level\n  sound [523 100 659 100 784 150]\nend\n\nto high.score\n  make "file "/projects/starcatcher.txt\n  make "best 0\n  if filep :file [\n    openread :file\n    setread :file\n    make "best first readlist\n    setread []\n    close :file\n  ]\n  if :score > :best [\n    print [A new high score!]\n    openwrite :file\n    setwrite :file\n    print :score\n    setwrite []\n    close :file\n    stop\n  ]\n  print sentence [The high score is still] :best\nend\n\nto play\n  setup\n  print [Click the turtle world, then press the left and right arrow keys.]\n  until [:lives = 0] [steer fall check wait 1]\n  print sentence [Game over. Your score:] :score\n  high.score\nend\n\nplay\n', check: { output: 'high score' } },
        { title: 'Levels', text: '<code>remainder :score 5</code> is 0 when the score is 5, 10, 15 and so on. Each time, LEVEL.UP adds 1 to <code>:speed</code>, so FALL moves the star further each time round the loop.' },
        { title: 'The high score file', text: 'HIGH.SCORE reads the best score from <b>/projects/starcatcher.txt</b> if the file exists (FILEP), and writes the new score there if you beat it. READLIST gives a list like [7], so FIRST takes the number out.' },
        { title: 'Play twice', sel: '#cmdInputBox', text: 'Type <code>play</code> to play another game. This time it compares your score with the one saved last time.', check: { output: 'high score' } },
        { title: 'Find the file', sel: '#railFiles', text: 'Open <b>Files</b> and look in <b>/projects</b> for starcatcher.txt. It holds just one number: your best score.' },
        { title: 'Make it yours', sel: '#editorCard', text: 'Now change the game. Some ideas: show the level in the game over message, make the catcher wider by catching within 40 steps, add a second star (turtle 2), or a bonus life every 10 stars. Run it when you are done.', check: { run: true } },
        { title: 'Quick quiz', quiz: { q: 'Why does the high score survive when you run the program again?', options: ['It is saved in a file, and files are not forgotten on a fresh start', 'Variables are never forgotten', 'The turtle remembers it'], answer: 0, explain: 'A fresh start forgets variables, but /projects/starcatcher.txt stays.' } },
        { title: 'You made a game', text: 'Star Catcher uses almost everything from this course: procedures, variables, decisions, loops, keys, several turtles, sound and files. From here, try the <b>Library</b> for more programs to read and change, or invent a game of your own.' },
      ] },
  ]);
})(LG);
